function exploreOrchestration(params: { question_id: string }) {
  const files = listFiles();
  const relevantFiles = files.filter(file => 
    file.includes('orchestration') || 
    file.includes('Mistral') || 
    file.includes('model') || 
    file.includes('harness') ||
    file.includes('tool') ||
    file.includes('exploration')
  );

  const searchTerms = [
    'Mistral',
    'model',
    'orchestrate',
    'tool',
    'exploration',
    'listFiles',
    'searchText',
    'searchIdentifiers',
    'readLines',
    'readAround',
    'listSymbols',
    'findDefinitions',
    'findReferences',
    'getImports',
    'getGitDiff'
  ];

  const results: {file: string, line: number, text: string}[] = [];

  for (const file of relevantFiles) {
    const matches = searchText(searchTerms.join('|'));
    const fileMatches = matches.filter(match => match.file === file);
    results.push(...fileMatches);
  }

  return {
    relevantFiles,
    results
  };
}

function exploreOrchestration(params: { question_id: string }) {
  const allFiles = listFiles();

  // Filter files likely related to orchestration, Mistral, or tools
  const relevantFiles = allFiles.filter(file => 
    file.includes('index') || 
    file.includes('harness') || 
    file.includes('orchestration') || 
    file.includes('Mistral') || 
    file.includes('model') || 
    file.includes('tool') || 
    file.includes('agent') ||
    file.includes('exploration')
  );

  // Search for key terms in all files
  const searchResults = searchText('Mistral|model|orchestrate|harness|listFiles|searchText|searchIdentifiers|readLines|readAround|listSymbols|findDefinitions|findReferences|getImports|getGitDiff');

  return {
    relevantFiles,
    searchResults
  };
}

